/**
 * compute-admin-metrics-daily — nightly snapshot for the founder admin
 * dashboard's trend charts.
 *
 * Calls the three public.founder_metrics_*() functions (migration 101) and
 * upserts one row per IST day into public.admin_metrics_daily (migration
 * 102). A live query can only ever show "right now" — this snapshot is what
 * makes "how did PRO count move over the last 30 days" answerable at all.
 *
 * Trigger: cron only (pg_cron, 23:45 IST daily — see migration 102). No
 * manual/admin invocation path; unlike promote-community-item there's no
 * legitimate reason for a human to trigger this outside the schedule.
 *
 * Idempotency: `admin_metrics_daily.snapshot_date` is UNIQUE; the upsert
 * below uses `onConflict: 'snapshot_date'` so a pg_cron retry (pg_cron does
 * not guarantee exactly-once execution) corrects the same day's row instead
 * of creating a duplicate that would corrupt every trend chart.
 */

import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { corsHeaders, ok, serverError } from "../_shared/error.ts";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { logCronEnd, logCronStart } from "../_shared/cron_telemetry.ts";
import { istDateStr } from "../_shared/ist_date.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

interface GrowthRow {
  total_users: number | null;
  signups_today_ist: number | null;
  signups_7d: number | null;
  signups_30d: number | null;
  pro_active: number | null;
  pro_expired: number | null;
  free_users: number | null;
  active_subscriptions: number | null;
  active_last_7d: number | null;
  generated_at: string;
}

interface EngagementRow {
  workouts_logged_today: number | null;
  food_logs_today: number | null;
  ai_messages_today: number | null;
  streak_maintained_current_week: number | null;
  generated_at: string;
}

interface OpsRow {
  client_errors_today: number | null;
  client_errors_7d: number | null;
  open_alerts_count: number | null;
  cron_failures_24h: number | null;
  generated_at: string;
}

export interface SnapshotRow {
  snapshot_date: string;
  total_users: number;
  signups_today_ist: number;
  signups_7d: number;
  signups_30d: number;
  pro_active: number;
  pro_expired: number;
  free_users: number;
  active_subscriptions: number;
  active_last_7d: number;
  workouts_logged_today: number;
  food_logs_today: number;
  ai_messages_today: number;
  streak_maintained_current_week: number;
  client_errors_today: number;
  client_errors_7d: number;
  open_alerts_count: number;
  cron_failures_24h: number;
}

const n = (v: number | null | undefined): number => v ?? 0;

/**
 * Merge the three RPC results into one admin_metrics_daily row. Pure —
 * no I/O, no Date.now(). Every numeric field is coalesced to 0 (never
 * null) so downstream trend/delta math never has to null-check.
 */
export function buildSnapshotRow(
  snapshotDate: string,
  growth: GrowthRow,
  engagement: EngagementRow,
  ops: OpsRow,
): SnapshotRow {
  return {
    snapshot_date: snapshotDate,
    total_users: n(growth.total_users),
    signups_today_ist: n(growth.signups_today_ist),
    signups_7d: n(growth.signups_7d),
    signups_30d: n(growth.signups_30d),
    pro_active: n(growth.pro_active),
    pro_expired: n(growth.pro_expired),
    free_users: n(growth.free_users),
    active_subscriptions: n(growth.active_subscriptions),
    active_last_7d: n(growth.active_last_7d),
    workouts_logged_today: n(engagement.workouts_logged_today),
    food_logs_today: n(engagement.food_logs_today),
    ai_messages_today: n(engagement.ai_messages_today),
    streak_maintained_current_week: n(engagement.streak_maintained_current_week),
    client_errors_today: n(ops.client_errors_today),
    client_errors_7d: n(ops.client_errors_7d),
    open_alerts_count: n(ops.open_alerts_count),
    cron_failures_24h: n(ops.cron_failures_24h),
  };
}

export const handler = async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (!await isAuthorizedCronCall(req)) {
    return new Response(
      JSON.stringify({ error: "Unauthorized" }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  const logId = await logCronStart("compute-admin-metrics-daily");

  try {
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const [growthRes, engagementRes, opsRes] = await Promise.all([
      supabase.rpc("founder_metrics_for_admin_api").single(),
      supabase.rpc("founder_metrics_engagement").single(),
      supabase.rpc("founder_metrics_ops").single(),
    ]);

    if (growthRes.error || engagementRes.error || opsRes.error) {
      const errorSummary = [growthRes.error, engagementRes.error, opsRes.error]
        .filter(Boolean)
        .map((e) => e!.message)
        .join(" | ");
      await logCronEnd(logId, "failed", { httpStatus: 500, errorSummary });
      return serverError(
        "compute-admin-metrics-daily:rpc",
        new Error(errorSummary),
      );
    }

    const snapshotDate = istDateStr();
    const row = buildSnapshotRow(
      snapshotDate,
      growthRes.data as GrowthRow,
      engagementRes.data as EngagementRow,
      opsRes.data as OpsRow,
    );

    const { error: upsertError } = await supabase
      .from("admin_metrics_daily")
      .upsert(row, { onConflict: "snapshot_date" });

    if (upsertError) {
      await logCronEnd(logId, "failed", {
        httpStatus: 500,
        errorSummary: upsertError.message,
      });
      return serverError("compute-admin-metrics-daily:upsert", upsertError);
    }

    await logCronEnd(logId, "success", { httpStatus: 200 });
    return ok({ ok: true, snapshot_date: snapshotDate });
  } catch (err) {
    await logCronEnd(logId, "failed", {
      httpStatus: 500,
      errorSummary: String(err).slice(0, 500),
    });
    return serverError("compute-admin-metrics-daily", err);
  }
};

if (import.meta.main) {
  serve(handler);
}

// Shared error sanitization for Edge Functions.
//
// Rule: the client NEVER sees raw exception messages, stack traces, upstream
// provider responses, SQL hints, or environment-shaped strings. Unexpected
// failures are logged server-side with full detail and returned to the client
// as a generic `Internal server error` plus a request_id the user can quote
// when contacting support.
//
// Intentional 4xx validation errors (e.g. "Message too long", "Snapshot too
// large", "Image too large", "Only Supabase Storage URLs are allowed", "PRO
// subscription required") are kept verbatim and should NOT flow through this
// helper. Use `clientError()` to return those directly with the correct
// status code.

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
};

/**
 * Generate a short, URL-safe request id for correlating client-reported
 * failures to server logs. Not cryptographically significant — just enough
 * entropy to disambiguate concurrent requests.
 */
export function newRequestId(): string {
  // crypto.randomUUID is available in Deno runtime
  const uuid = crypto.randomUUID();
  // Return first 8 chars — plenty for log lookup, short enough to quote.
  return uuid.split("-")[0];
}

/**
 * Build a sanitised 5xx response. Logs full details to stderr; returns a
 * generic body to the client with a request_id they can quote.
 *
 * @param context short string identifying the Edge Function / operation
 * @param err the caught error (any type)
 * @param extraHeaders optional additional headers to merge with corsHeaders
 */
export function serverError(
  context: string,
  err: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  const requestId = newRequestId();
  const detail = err instanceof Error
    ? { message: err.message, stack: err.stack, name: err.name }
    : { value: String(err) };
  // Full detail stays on the server — ops, logs, Sentry, whatever.
  console.error(
    `[${context}] request_id=${requestId}`,
    JSON.stringify(detail),
  );
  return new Response(
    JSON.stringify({
      error: "Internal server error",
      request_id: requestId,
    }),
    {
      status: 500,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * Build a 4xx response with a client-safe message. Use this for validation
 * errors (bad input, auth failures, quota exceeded, etc.) where the user
 * NEEDS the specific message to know what to do. Always safe — callers are
 * expected to pass only vetted, non-leaking strings.
 */
export function clientError(
  message: string,
  status: number,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify({ error: message }),
    {
      status,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * Convenience: JSON success response with CORS.
 */
export function ok(
  body: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify(body),
    {
      status: 200,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * cron_auth.ts — JWT signature + role-claim auth for cron Edge Functions.
 *
 * Audit 2026-05-16 / E.14.C (closes-diagnose: telemetry-hardening).
 *
 * BACKGROUND
 * ----------
 * Test #16 / P1-D documented a 401-storm root-cause class: every cron
 * Edge Function inlines an env-equality check shaped like:
 *
 *   const isServiceRole = !!serviceRoleKey && token === serviceRoleKey;
 *
 * This is brittle. When the Vault-stored JWT and the env-injected
 * `SUPABASE_SERVICE_ROLE_KEY` drift (platform rotation, manual Vault
 * re-save), the equality check fails and every cron tick returns 401
 * for hours/days before anyone notices — `cron.job_run_details` reports
 * "succeeded" regardless of the HTTP response.
 *
 * F9.1 (Agent 7 findings) flagged the lack of a shared helper as a
 * framework gap. This module is the replacement.
 *
 * AUTH MODEL
 * ----------
 * We decode the bearer token's JWT, verify the signature using the
 * project's `SUPABASE_JWT_SECRET` (Supabase auth signs all keys with
 * the same HS256 secret), and require `role === 'service_role'`.
 * Signature verification means a rotated key still authenticates as
 * long as it was signed by the same project secret — no env-drift
 * silent failure.
 *
 * The legacy `CRON_SECRET` opaque-token escape hatch is preserved so
 * we can rollback per-function if jose import or signature verify
 * misbehaves on Deno Deploy edge.
 *
 * USAGE (per-cron-function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(
 *         JSON.stringify({ error: "Unauthorized" }),
 *         { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
 *       );
 *     }
 *     // ... handler body
 *   });
 *
 * NOTE — DO NOT DEPLOY in this batch. Source edit only; founder must
 * approve per-function deploys (live Edge Function deploys are gated).
 */

// Tech-debt audit 2026-05-20 D12: bumped jose v5.6.3 → v5.9.6 (security
// patches in 5.7.x/5.8.x/5.9.x). Gate: scripts/check_jose_version.dart.
import { jwtVerify } from "https://deno.land/x/jose@v5.9.6/index.ts";

/**
 * Returns true when the request's Authorization header carries either:
 *
 *   (a) a JWT signed by `SUPABASE_JWT_SECRET` with `role === 'service_role'`, OR
 *   (b) an opaque token exactly matching `CRON_SECRET` (legacy/escape hatch).
 *
 * False on missing header, malformed bearer, invalid signature, expired
 * token, wrong role claim, or any internal error. Safe to call without
 * try/catch — never throws.
 *
 * Env vars consulted:
 *   - SUPABASE_JWT_SECRET (required for JWT path)
 *   - CRON_SECRET         (optional escape hatch)
 *
 * Pinned by the diagnose-doc; not unit-tested at this revision because
 * jose's WebCrypto path is hard to mock in-process. Replace with a
 * decode-only mock in tests when adding coverage.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Escape hatch — opaque CRON_SECRET match. Kept so a per-function
    // rollback is one env var away if jose / signature verify breaks.
    const cronSecret = Deno.env.get("CRON_SECRET");
    if (cronSecret && cronSecret.length > 0 && token === cronSecret) {
      return true;
    }

    // JWT signature + role-claim path.
    const jwtSecret = Deno.env.get("SUPABASE_JWT_SECRET");
    if (!jwtSecret || jwtSecret.length === 0) {
      console.warn("[cron_auth] SUPABASE_JWT_SECRET unset; cannot verify JWT");
      return false;
    }
    const secretKey = new TextEncoder().encode(jwtSecret);

    let payload: Record<string, unknown>;
    try {
      const verified = await jwtVerify(token, secretKey);
      payload = verified.payload as Record<string, unknown>;
    } catch (err) {
      console.warn(`[cron_auth] jwtVerify failed: ${(err as Error).message}`);
      return false;
    }

    const role = payload["role"];
    if (role !== "service_role") {
      console.warn(`[cron_auth] role claim mismatch: got ${String(role)}`);
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let auth-gate code crash the caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/**
 * cron_telemetry — per-invocation execution telemetry for cron Edge Functions.
 *
 * Closes audit 2026-05-17 / OI-15. Background: `cron.job_run_details.status='succeeded'`
 * only confirms the pg_cron-side `net.http_post()` dispatch succeeded; it does NOT
 * reflect the Edge Function's actual HTTP response. During the Vault drift incident
 * (2026-05-11..16, CLAUDE.md §19 entry "pr-detection cron loops 401 every 15 min"),
 * pg_cron reported 1066 "succeeded" runs across a week while every single call returned
 * 401 server-side and zero work happened.
 *
 * Each cron Edge Function imports this helper and:
 *   1. Calls `logCronStart(name)` at the top of its `serve` handler → returns a row id.
 *   2. Calls `logCronEnd(id, status, httpStatus?, errorSummary?)` before returning.
 *
 * The row lands in `public.cron_call_log` (migration 068). Retention: 7 days via
 * `public.cleanup_cron_call_log()` (must be wired by founder via pg_cron registration
 * — currently not scheduled; see open_issues.md OI-15 follow-up).
 *
 * Failures inside the telemetry call itself are SWALLOWED (try/catch + debug log).
 * Cron functions MUST NOT 500 because telemetry is broken.
 */

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

type CronLogStatus = "success" | "failed";

let _adminClient: SupabaseClient | null = null;

function adminClient() {
  if (_adminClient) return _adminClient;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    // Edge runtime quirk — should never happen in prod, but don't crash if it does.
    return null;
  }
  _adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  return _adminClient;
}

/**
 * Insert a `started` row. Returns the row id so the caller can update on exit.
 *
 * Returns `null` if telemetry insert fails — callers should pass that null straight
 * back into `logCronEnd` (which is a no-op on null id). The function itself never
 * throws.
 */
export async function logCronStart(functionName: string): Promise<number | null> {
  try {
    const supabase = adminClient();
    if (!supabase) return null;
    const { data, error } = await supabase
      .from("cron_call_log")
      .insert({ function_name: functionName, status: "started" })
      .select("id")
      .single();
    if (error || !data) {
      console.warn(`[cron_telemetry] start insert failed for ${functionName}`, error);
      return null;
    }
    return (data as { id: number }).id;
  } catch (e) {
    console.warn(`[cron_telemetry] start exception for ${functionName}`, e);
    return null;
  }
}

/**
 * Update the row created by `logCronStart` with terminal status.
 *
 * Passes-through silently when `id` is null (i.e. start insert failed).
 */
export async function logCronEnd(
  id: number | null,
  status: CronLogStatus,
  opts?: { httpStatus?: number; requestId?: string; errorSummary?: string },
): Promise<void> {
  if (id == null) return;
  try {
    const supabase = adminClient();
    if (!supabase) return;
    const patch: Record<string, unknown> = { status };
    if (opts?.httpStatus !== undefined) patch.http_status = opts.httpStatus;
    if (opts?.requestId) patch.request_id = opts.requestId;
    if (opts?.errorSummary) {
      // Cap error summary at 1000 chars to avoid bloat from giant stack traces.
      patch.error_summary = opts.errorSummary.slice(0, 1000);
    }
    const { error } = await supabase
      .from("cron_call_log")
      .update(patch)
      .eq("id", id);
    if (error) {
      console.warn(`[cron_telemetry] end update failed for id=${id}`, error);
    }
  } catch (e) {
    console.warn(`[cron_telemetry] end exception for id=${id}`, e);
  }
}

// supabase/functions/_shared/ist_date.ts
// IST (UTC+5:30) date helpers shared across Edge Functions.
// Mirrors lib/core/utils/ist_date.dart on the Flutter client so both sides
// agree on what "today" means.

export const IST_OFFSET_MS = (5 * 60 + 30) * 60 * 1000;

/// Returns a new Date object shifted to IST (UTC+5:30).
export function istNow(d: Date = new Date()): Date {
  return new Date(d.getTime() + IST_OFFSET_MS);
}

/// Returns 'YYYY-MM-DD' in IST.
export function istDateStr(d: Date = new Date()): string {
  const ist = istNow(d);
  return ist.toISOString().substring(0, 10);
}

/// Returns day-of-week in IST (Sun=0 .. Sat=6).
/// Mirrors JavaScript's getDay() but computed in IST, not the server's local TZ.
export function istDayOfWeek(d: Date = new Date()): number {
  return istNow(d).getUTCDay();
}

/// Returns IST midnight (00:00:00 IST) for the given date as a
/// timestamptz-comparable ISO string carrying the +05:30 offset.
/// Use this for cloud rate-limit / cap queries like
/// `.gte("created_at", istDayStartIso())` so the "today" window
/// aligns with the user's IST day instead of UTC midnight (a 5h30m
/// drift that gives Indian users a stale rate-limit reset at
/// 05:30 IST every morning).
///
/// audit-2026-05-11 H-4 / H-10 — ai-proxy + ai-media-proxy vision
/// caps + free-tier message count were filtering against UTC
/// midnight; switched to this helper.
export function istDayStartIso(d: Date = new Date()): string {
  return `${istDateStr(d)}T00:00:00+05:30`;
}
